"""F0(c): is the robot's silhouette in the fixed eagle image the same for a given pedestal height at the zombie pose, wherever the base stands?

    python experiments/f0_silhouette_check.py

Renders the robot-only silhouette (src/bench_stance.robot_silhouettes) and the arms' pixel mask of the real scene (OcclusionMeter) at several stances for three pedestal heights, and compares them.
"""
import numpy as np

from src import bench_stance as bs
from src.robot_helpers import arm_ids  # noqa: F401
from src.stance_checks import OcclusionMeter, StanceChecks
from src.stance_finder import robot_geometry
from src.task_beaker_hotplate import load_task
from src.task_config import TASK_CFG

if __name__ == "__main__":
    sim = load_task()
    m, d = sim.model, sim.data
    rg = robot_geometry(m)
    chk = StanceChecks(m, d, rg["base_z"])
    qs = [0.05, 0.155, 0.25]
    stances = [(TASK_CFG["staging_xy"][0], TASK_CFG["staging_xy"][1], TASK_CFG["staging_yaw"]), (0.40, 1.30, -1.0), (1.50, 1.10, -2.0)]
    sil = [bs.robot_silhouettes(m, chk, qs, st) for st in stances]          # three separate sets of renders (no cache)
    for i in (1, 2):
        print(f"robot-only silhouette, stance 0 vs {i}: identical for all heights: {bool((sil[0] == sil[i]).all())}; pixels differing: {int((sil[0] != sil[i]).sum())}; robot pixels {int(sil[0].sum())}")
    meter = OcclusionMeter(m)
    for qi, q in enumerate(qs):
        masks = []
        for st in stances:
            chk.place((*st, q))
            masks.append(meter.measure(chk.d, masks=True)["arm_mask"])
        print(f"q {q}: arms' pixel mask in the real scene, stances 1 and 2 against stance 0: differing pixels {int((masks[0] != masks[1]).sum())}, {int((masks[0] != masks[2]).sum())} of {int(masks[0].sum())} arm pixels;"
              f" arm pixels outside the robot-only silhouette: {int((masks[0] & ~sil[0][qi]).sum())}")

    import time
    t0 = time.time()
    maps = bs.load_maps("data/reach_map")
    print(f"F0(d): loading the 24 maps (both arms) from disk: {time.time() - t0:.2f} s")
    t0 = time.time()
    left = bs.load_maps("data/reach_map", sides=("left",))
    print(f"F0(d): loading one arm's 12 bin maps (left), not merged: {time.time() - t0:.2f} s ({len(left)} maps)")
